// Launch the same pinned REA MCP package on Windows, macOS, and Linux.
const { spawn } = require("node:child_process");
const windows = process.platform === "win32";
const args = ["--yes", "--ignore-scripts", "--omit=optional", "rea-agents@6.5.0", "mcp"];
const child = windows
  ? spawn("cmd.exe", ["/d", "/c", "npx", ...args], { stdio: "inherit", windowsHide: true })
  : spawn("npx", args, { stdio: "inherit" });
child.on("error", (error) => { process.stderr.write(`REA MCP launch failed: ${error.message}\n`); process.exitCode = 1; });
child.on("exit", (code) => { process.exitCode = code === null ? 1 : code; });
